134:     if ((NLMSG_ALIGN(n->nlmsg_len) + RTA_ALIGN(len)) > maxlen)
135:     {
136:         msg(M_WARN, "%s: rtnl: message exceeded bound of %zu", __func__, maxlen);
137:         return -EMSGSIZE;
138:     }
